            // used by the maxNumberOfFiles validation:
            getNumberOfFiles: function () {
                return this.filesContainer.children().not('.processing').length;
            },

            // Callback to retrieve the list of files from the server response:
            getFilesFromResponse: function (data) {
                if (data.result && $.isArray(data.result.files)) {
                    return data.result.files;
                }
                return [];
            },

            // The add callback is invoked as soon as files are added to the fileupload
            // widget (via file input selection, drag & drop or add API call).
            // See the basic file upload widget for more information:
            add: function (e, data) {
                if (e.isDefaultPrevented()) {
                    return false;
                }


                var $this = $(this),
                    that = $this.data('blueimp-fileupload') || $this.data('fileupload'),
                    options = that.options;
                data.context = that
                    ._renderUpload(data.files)
                    .data('data', data)
                    .addClass('processing');
                options.filesContainer[options.prependFiles ? 'prepend' : 'append'](
                    data.context
                );
                that._forceReflow(data.context);
                that._transition(data.context);
                data
                    .process(function () {
                        return $this.fileupload('process', data);
                    })
                    .always(function () {
                        data.context
                            .each(function (index) {
                                $(this)
                                    .find('.size')
                                    .text(that._formatFileSize(data.files[index].size));
                            })
                            .removeClass('processing');
                        //liewen
                        //    that._renderPreviews(data);





                    })
                    .done(function () {

                        jQuery('#startUpload').prop('disabled', false);

                        jQuery('#startUpload, #addFiles').show();

                        window.cefQuery({
                            request: 'Prompt.q.active:0'
                        });



                        data.context.find('.edit,.start').prop('disabled', false);
                        if (
                            that._trigger('added', e, data) !== false &&
                            (options.autoUpload || data.autoUpload) &&
                            data.autoUpload !== false
                        ) {
                            data.submit();
                        }
                    })
                    .fail(function () {
                        if (data.files.error) {
                            data.context.each(function (index) {
                                var error = data.files[index].error;
                                if (error) {
                                    $(this)
                                        .find('.error')
                                        .text(error);
                                }
                            });
                        }
                    });
            },


            // Callback for the start of each file upload request:
            send: function (e, data) {
                if (e.isDefaultPrevented()) {
                    return false;
                }
                var that =
                    $(this).data('blueimp-fileupload') || $(this).data('fileupload');

                //liewen
                jQuery('#uploadingActions').show();
                var file = data.files[0];
                //var fileTypes = /(\.|\/)(mp3|mp4)$/i;
                //if (fileTypes.test(file.name)){
                if (file.size > 10 * 1024 * 1024) {
                    var interval;
                    var nb = 7;
                    if (file.size > 500 * 1024 * 1024) {
                        nb = 53;
                    }
                    else if (file.size > 200 * 1024 * 1024) {
                        nb = 23
                    }
                    else if (file.size > 100 * 1024 * 1024) {
                        nb = 13
                    }

                    var total_step = 0;
                    interval = setInterval(function () {
                        var nstep = file.size / nb;
                        if (_all_cancel > 0) {
                            clearInterval(interval);
                        }
                        else if (data.loaded + nstep < data.total) {
                            data.loaded += nstep;
                            total_step += nstep;

                            that._trigger(
                                'progress',
                                $.Event('progress', { delegatedEvent: e }),
                                data
                            );

                            that._progress.loaded += nstep;
                            that._trigger(
                                'progressall',
                                $.Event('progressall', { delegatedEvent: e }),
                                that._progress
                            );
                        }
                        else {
                            if (data.loaded == data.total) {
                                clearInterval(interval);

                                that._trigger(
                                    'progress',
                                    $.Event('progress', { delegatedEvent: e }),
                                    data
                                );

                                that._progress.loaded += file.size - total_step;
                                that._trigger(
                                    'progressall',
                                    $.Event('progressall', { delegatedEvent: e }),
                                    that._progress
                                );
                            }
                        }

                    }, 1000);
                }
                else {
                    data.loaded += file.size;
                    that._trigger(
                        'progress',
                        $.Event('progress', { delegatedEvent: e }),
                        data
                    );
                }

                if (
                    data.context &&
                    data.dataType &&
                    data.dataType.substr(0, 6) === 'iframe'
                ) {
                    // Iframe Transport does not support progress events.
                    // In lack of an indeterminate progress bar, we set
                    // the progress to 100%, showing the full animated bar:
                    data.context
                        .find('.progress')
                        .addClass(!$.support.transition && 'progress-animated')
                        .attr('aria-valuenow', 100)
                        .children()
                        .first()
                        .css('width', '100%');
                }
                return that._trigger('sent', e, data);
            },

            //liewen
